import { html, nothing, type PropertyValues } from 'lit'
import { PanelLeftClose, PanelLeftOpen } from 'lucide'
import { DsElement, define, HostLayoutController, tagName } from '@/elements/lib/element'
import { icon } from '@/elements/lib/icon'
import styles from 'virtual:tw'

// Sidebar.tsx as <spyglass-sidebar>: the app's rail, Black with a hairline at its edge, 256px wide. The `head` slot
// holds the logo or the workspace (56px, over a hairline), <spyglass-sidebar-label> names each group, a
// <spyglass-sidebar-link> per page (the page you are on in White), and the `foot` slot the account. `collapsible` adds a
// button that folds it to 64px of icons, at once; `collapsed` (reflected) with `collapsed-change`.

/**
 * @summary The app's navigation rail, with groups of links.
 * @slot - Labels and links.
 * @slot head - The logo or the workspace.
 * @slot foot - The account.
 * @fires collapsed-change - It folded or unfolded (detail.value).
 */
export class Sidebar extends DsElement {
	static styles = [DsElement.styles, styles]
	protected readonly layout = new HostLayoutController(this, () => this.renderRoot.querySelector<HTMLElement>('nav'))
	static properties = { label: {}, collapsible: { type: Boolean }, collapsed: { type: Boolean, reflect: true } }

	/** The navigation's name for assistive tech. */
	label = 'Main'
	/** Shows the button that folds it to icons. */
	collapsible = false
	/** Folded to icons. */
	collapsed = false

	protected updated(changed: PropertyValues) {
		super.updated(changed)
		// The links and labels draw themselves from the sidebar's state.
		if (changed.has('collapsed')) for (const el of this.querySelectorAll<DsElement>(`${tagName('sidebar-link')}, ${tagName('sidebar-label')}`)) el.requestUpdate()
	}

	render() {
		const head = this.hasSlot('head')
		const Icon = this.collapsed ? PanelLeftOpen : PanelLeftClose
		return html`<nav data-ds="sidebar" aria-label=${this.label} ?data-collapsed=${this.collapsed} class=${`flex h-full shrink-0 flex-col border-r border-edge bg-surface ${this.collapsed ? 'w-16' : 'w-rail'}`}>
			${head || this.collapsible
				? html`<div class=${`flex h-14 shrink-0 items-center gap-2 border-b border-edge px-3 ${this.collapsed ? 'justify-center' : 'justify-between'}`}>
					${head && !this.collapsed ? html`<div class="flex min-w-0 flex-1 items-center pl-1"><slot name="head"></slot></div>` : nothing}
					${this.collapsible ? html`<button type="button" class="inline-flex size-control-md shrink-0 cursor-pointer items-center justify-center rounded-control text-fg-muted transition-[background-color,color] duration-160 ease-standard hover:bg-action-ghost-hover hover:text-fg" aria-label=${this.collapsed ? 'Expand sidebar' : 'Collapse sidebar'} aria-expanded=${String(!this.collapsed)} @click=${() => this.commit(!this.collapsed, 'collapsed')}>${icon(Icon, this.collapsed ? 'panel-left-open' : 'panel-left-close', { size: 16, strokeWidth: 1.5, attrs: { 'aria-hidden': 'true' } })}</button>` : nothing}
				</div>`
				: nothing}
			<div class="flex min-h-0 flex-1 flex-col gap-0.5 overflow-y-auto p-3 fade-y"><slot></slot></div>
			${this.hasSlot('foot') ? html`<div class=${`shrink-0 border-t border-edge p-3 ${this.collapsed ? 'hidden' : ''}`}><slot name="foot"></slot></div>` : nothing}
		</nav>`
	}
}

define('sidebar', Sidebar)

import { html } from 'lit'
import { DsElement, define, tagName } from '@/elements/lib/element'
import styles from 'virtual:tw'

// SidebarLabel.tsx as <spyglass-sidebar-label>: a group's name in the sidebar, DM Sans Medium in capitals at 6%,
// muted, 16px over it. Folded to icons, a hairline takes its place and the name stays for assistive tech.

/**
 * @summary A group's name in the sidebar.
 * @slot - The name.
 */
export class SidebarLabel extends DsElement {
	static styles = [DsElement.styles, styles]

	render() {
		const collapsed = !!(this.closest(tagName('sidebar')) as (Element & { collapsed?: boolean }) | null)?.collapsed
		// The first in the sidebar's body (the head and foot slots' content aside), as :first-child is in React's.
		let prev = this.previousElementSibling
		while (prev?.hasAttribute('slot')) prev = prev.previousElementSibling
		const first = !prev
		return html`<div data-ds="sidebar-label" class=${first ? 'pt-1 pb-2' : 'pt-4 pb-2'}>${collapsed ? html`<div class="mx-2 border-t border-edge" aria-hidden="true"></div>` : ''}<p class=${collapsed ? 'sr-only' : 'px-3 type-label text-fg-muted'}><slot></slot></p></div>`
	}
}

define('sidebar-label', SidebarLabel)

import { html, nothing } from 'lit'
import { ifDefined } from 'lit/directives/if-defined.js'
import { DsElement, define, HostLayoutController, tagName } from '@/elements/lib/element'
import styles from 'virtual:tw'

// SidebarLink.tsx as <spyglass-sidebar-link>: one page in the sidebar, a 40px row (44px on phones) with its icon (an
// <i data-lucide> in the `icon` slot), the label and a count (`status`) at the end. The page you are on (`active`) is
// White with Black type; the others are soft gray and fill on hover. Folded to icons, the row is a 40px square.

/**
 * @summary One page in the sidebar.
 * @slot - The label.
 * @slot icon - A Lucide icon.
 */
export class SidebarLink extends DsElement {
	static styles = [DsElement.styles, styles]
	protected readonly layout = new HostLayoutController(this, () => this.renderRoot.querySelector<HTMLElement>('a'))
	static properties = { href: {}, active: { type: Boolean, reflect: true }, status: {} }

	href?: string
	/** The page you are on. */
	active = false
	/** A count at the end of the row. */
	status?: string

	render() {
		const collapsed = !!(this.closest(tagName('sidebar')) as (Element & { collapsed?: boolean }) | null)?.collapsed
		const classes = [
			'flex h-row shrink-0 cursor-pointer items-center gap-3 rounded-control type-ui -outline-offset-2 transition-[background-color,color] duration-160 ease-standard max-md:h-control-touch',
			collapsed ? 'w-row justify-center px-0' : 'px-3',
			this.active ? 'bg-action-primary text-action-primary-fg' : 'text-fg-soft hover:bg-action-ghost-hover hover:text-fg',
		].join(' ')
		return html`<a data-ds="sidebar-link" href=${ifDefined(this.href)} aria-current=${ifDefined(this.active ? 'page' : undefined)} class=${classes}>${this.hasSlot('icon') ? html`<span class=${`flex shrink-0 ${this.active ? 'text-action-primary-fg' : 'text-fg-muted'}`}><slot name="icon"></slot></span>` : nothing}<span class=${collapsed ? 'sr-only' : 'min-w-0 flex-1 truncate'}><slot></slot></span>${this.status && !collapsed ? html`<span class=${`type-caption tabular-nums ${this.active ? 'text-action-primary-fg' : 'text-fg-muted'}`}>${this.status}</span>` : nothing}</a>`
	}
}

define('sidebar-link', SidebarLink)
